# Linx, passed through nginx by name (docs/WEB.md §3). Generated by linx setup.
# Goes in nginx.conf at the top level (next to http { }, not inside it).
# nginx needs the stream module (in nginx.org's and Debian's nginx packages).
stream {
    map $ssl_preread_server_name $linx_route {
        example.com       192.168.1.212:8443;
        turn.example.com  127.0.0.1:4445;
        default     127.0.0.1:4443;
    }

    server {
        listen 443;
        ssl_preread on;
        proxy_protocol on;
        proxy_pass $linx_route;
    }

    # Relay over TLS: coturn can't read PROXY headers, so they're dropped here.
    server {
        listen 127.0.0.1:4445 proxy_protocol;
        proxy_pass 192.168.1.212:5349;
    }
}

# Linx at example.com, passed through Caddy by name (docs/SIMPLER.md §2).
# Generated by Linx. Needs Caddy with the layer4 add-on (caddy-l4).
{
	servers {
		listener_wrappers {
			layer4 {
				@linx_web tls sni example.com
				route @linx_web {
					proxy {
						proxy_protocol v2
						upstream 192.168.1.212:8443
					}
				}
				@linx_turn tls sni turn.example.com
				route @linx_turn {
					proxy 192.168.1.212:5349
				}
			}
			tls
		}
		# Call audio uses UDP 443, so no HTTP/3 for Caddy's own sites.
		protocols h1 h2
	}
}
